import { Injectable, OnApplicationBootstrap } from '@nestjs/common';
import { EventEmitter2, EventEmitterReadinessWatcher } from '@nestjs/event-emitter';

@Injectable()
export class BootstrapService implements OnApplicationBootstrap {
  constructor(
    private readonly watcher: EventEmitterReadinessWatcher,
    private readonly eventEmitter: EventEmitter2,
  ) {}

  async onApplicationBootstrap() {
    await this.watcher.waitUntilReady();
    this.eventEmitter.emit('app.ready', { at: Date.now() });
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { Cron, SchedulerRegistry } from '@nestjs/schedule';

@Injectable()
export class TasksService {
  private readonly logger = new Logger(TasksService.name);

  constructor(private readonly schedulerRegistry: SchedulerRegistry) {}

  @Cron('45 * * * * *', { name: 'cleanup' })
  handleCron() {
    this.logger.debug('Called when the current second is 45');
  }

  stopCleanup() {
    const job = this.schedulerRegistry.getCronJob('cleanup');
    job.stop();
    this.logger.log(`last run: ${job.lastDate()}`);
  }
}

import { Injectable } from '@nestjs/common';
import { SchedulerRegistry } from '@nestjs/schedule';

@Injectable()
export class IntervalsService {
  constructor(private readonly schedulerRegistry: SchedulerRegistry) {}

  addInterval(name: string, milliseconds: number) {
    const callback = () => console.log(`Interval ${name} executing`);
    const interval = setInterval(callback, milliseconds);
    this.schedulerRegistry.addInterval(name, interval);
  }

  listIntervals() {
    this.schedulerRegistry.getIntervals().forEach((key) => console.log(key));
  }
}
